class SgfTree:
    def __init__(self, properties=None, children=None):
        self.properties = properties or {}
        self.children = children or []

    def __eq__(self, other):
        if not isinstance(other, SgfTree):
            return False
        for key, value in self.properties.items():
            if key not in other.properties:
                return False
            if other.properties[key] != value:
                return False
        for key in other.properties.keys():
            if key not in self.properties:
                return False
        if len(self.children) != len(other.children):
            return False
        for child, other_child in zip(self.children, other.children):
            if child != other_child:
                return False
        return True

    def __ne__(self, other):
        return not self == other


def parse(input_string):
    if input_string is None or len(input_string) == 0:
        raise ValueError("tree missing")

    s = input_string
    n = len(s)
    i = 0

    def peek():
        return s[i] if i < n else None

    def consume():
        nonlocal i
        ch = s[i]
        i += 1
        return ch

    def parse_value():
        # caller should have consumed the opening '['
        nonlocal i
        buf = []
        while i < n:
            ch = s[i]
            if ch == ']':
                i += 1
                return ''.join(buf)
            if ch == '\\':
                i += 1
                if i >= n:
                    # escape at end before closing bracket -> invalid property delimiter
                    raise ValueError("properties without delimiter")
                nxt = s[i]
                # If newline after backslash, remove the newline (do not insert)
                if nxt == '\n':
                    i += 1
                    continue
                # Whitespace other than newline after backslash -> convert to space
                if nxt == '\t' or nxt == '\f' or nxt == '\v' or nxt == '\r' or nxt == ' ':
                    buf.append(' ')
                    i += 1
                    continue
                # any other char is inserted as-is
                buf.append(nxt)
                i += 1
                continue
            else:
                # Non-escaped character
                if ch == '\n':
                    buf.append('\n')
                elif ch == '\t' or ch == '\f' or ch == '\v' or ch == '\r' or ch == ' ':
                    buf.append(' ')
                else:
                    buf.append(ch)
                i += 1
        # if we exit loop without finding closing ]
        raise ValueError("properties without delimiter")

    def parse_property():
        nonlocal i
        # parse key: one or more uppercase A-Z letters
        if i >= n:
            raise ValueError("properties without delimiter")
        start = i
        # key letters must be uppercase A-Z
        while i < n and 'A' <= s[i] <= 'Z':
            i += 1
        if start == i:
            # no uppercase letters at all where property expected
            raise ValueError("property must be in uppercase")
        key = s[start:i]
        # If next char is a letter but not uppercase, that's invalid
        if i < n and s[i].isalpha() and not ('A' <= s[i] <= 'Z'):
            raise ValueError("property must be in uppercase")
        # After key, must have at least one value starting with '['
        values = []
        if i >= n or s[i] != '[':
            raise ValueError("properties without delimiter")
        # one or more values
        while i < n and s[i] == '[':
            # consume '['
            i += 1
            val = parse_value()
            values.append(val)
        return key, values

    def parse_node():
        nonlocal i
        # assumes current char is ';' and will consume it
        if peek() != ';':
            return None
        consume()  # consume ';'
        properties = {}
        # zero or more properties: each begins with uppercase letter
        # Stop when next char is one of ';', '(', ')', or end
        while True:
            ch = peek()
            if ch is None:
                break
            if 'A' <= ch <= 'Z':
                key, vals = parse_property()
                properties[key] = vals
                continue
            # if lowercase letter where a property key is expected -> error
            if 'a' <= ch <= 'z':
                raise ValueError("property must be in uppercase")
            # if next tokens indicate end of node or tree structure, stop parsing properties
            if ch in (';', '(', ')'):
                break
            # any other unexpected character at node position indicates missing delimiter
            raise ValueError("properties without delimiter")
        return properties

    def parse_tree():
        nonlocal i
        # tree must start with '('
        if peek() != '(':
            raise ValueError("tree missing")
        consume()  # '('
        # sequence: one or more nodes
        nodes = []
        # parse nodes while next is ';'
        while peek() == ';':
            props = parse_node()
            if props is None:
                break
            nodes.append(props)
        if len(nodes) == 0:
            # if no nodes in this tree, that's an error
            raise ValueError("tree with no nodes")
        # after nodes, there may be zero or more subtrees (variations)
        children_subtrees = []
        while peek() == '(':
            child_tree = parse_tree()
            children_subtrees.append(child_tree)
        # expect closing ')'
        if peek() != ')':
            raise ValueError("tree missing")
        consume()  # ')'

        # build SgfTree chain from nodes
        head = SgfTree(properties=nodes[0].copy(), children=[])
        current = head
        for props in nodes[1:]:
            child = SgfTree(properties=props.copy(), children=[])
            current.children = [child]
            current = child
        # attach children_subtrees to the last node in sequence
        if children_subtrees:
            current.children = children_subtrees
        return head

    if peek() != '(':
        raise ValueError("tree missing")
    tree = parse_tree()
    # After parsing a tree, there should be no extra characters (except maybe whitespace)
    while i < n and s[i].isspace():
        i += 1
    if i != n:
        raise ValueError("tree missing")
    return tree
